css:
.log-body p { margin: 0 0 0.4em; }
.log-body p:last-child { margin-bottom: 0; }
.log-body ul, .log-body ol { margin: 0.3em 0; padding-left: 1.5em; }
.log-body pre { margin: 0.3em 0; white-space: pre-wrap; font-size: 0.9em; }
.log-mention { font-weight: 600; color: var(--log-accent); }
.log-audio { color: var(--log-muted); font-size: 0.9em; }
.pb { height: 0; }
.cu-text { margin: 0; white-space: pre-wrap; }
.log-node--message { margin: 0 0 calc(var(--log-gap, 0.6) * 1em); }
.log-node--message.log-merged { margin-top: calc(var(--log-gap, 0.6) * -0.55em); }
.sc, .sc-dir, .hd, .tr, .cv, .pro, .toc, .ph, .pf { font-family: var(--log-face); }
.sc { display: grid; grid-template-columns: calc(var(--log-namewidth, 6) * 1em) 1fr; column-gap: 1.2em; font-size: 0.95em; line-height: 1.6; color: var(--log-ink); }
.sc-name { grid-column: 1; grid-row: 1; text-align: right; overflow-wrap: anywhere; }
.sc-n { font-weight: 700; letter-spacing: 0.04em; color: var(--log-speaker-color, var(--log-ink)); }
.sc-paren { display: block; font-size: 0.8em; font-weight: 400; color: var(--log-muted); }
.sc-line { grid-column: 2; grid-row: 1; min-width: 0; }
.log-merged .sc-name { visibility: hidden; }
.log-merged .sc-paren { display: none; }
.log-continued .sc::before { content: "（续）"; grid-column: 1; grid-row: 1; text-align: right; font-size: 0.8em; color: var(--log-muted); }
.sc-ooc { color: var(--log-muted); }
.sc-ooc .sc-n { color: var(--log-muted); font-weight: 600; }
.sc-dice .sc-line { padding-left: 0.7em; border-left: 2px solid var(--log-rule); font-size: 0.92em; }
.sc-line img { display: block; max-height: 14em; margin: 0.3em 0; }
.sc-dir { margin: 0.2em 0 calc(var(--log-gap, 0.6) * 1em) calc((var(--log-namewidth, 6) + 1.2) * 0.95em); padding: 0.05em 0 0.05em 0.8em; border-left: 1px solid var(--log-ink); line-height: 1.6; color: var(--log-muted); }
.sc-dir-line { font-size: 0.86em; }
.sc-dir-who { display: block; font-size: 0.75em; font-weight: 700; letter-spacing: 0.1em; color: var(--log-ink); }
.log-merged .sc-dir-who { display: none; }
.sc-narr { color: var(--log-ink); }
.cv { min-height: calc(var(--log-content-height, 180mm) * 0.92); display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; break-after: page; }
.cv-kind { margin-bottom: 2.4em; padding: 0.2em 0; border-top: 1px solid var(--log-ink); border-bottom: 1px solid var(--log-ink); font-size: 0.85em; letter-spacing: 0.6em; color: var(--log-ink); }
.cv-title { margin: 0 0 0.5em; font-size: 2em; line-height: 1.3; letter-spacing: 0.08em; color: var(--log-ink); }
.cv-sub { margin: 0; color: var(--log-muted); }
.cv-fig { margin: 2em auto 0; }
.cv-fig img { max-height: calc(var(--log-content-height, 180mm) * 0.4); }
.ip { margin: 1em 0; text-align: center; break-inside: avoid; }
.ip figcaption { margin-top: 0.4em; font-size: 0.85em; color: var(--log-muted); }
.tr { margin: 1.3em 0; text-align: var(--log-style-align, right); letter-spacing: 0.15em; color: var(--log-muted); }
.qt { margin: 1em 0 1em calc((var(--log-namewidth, 6) + 1.2) * 0.95em); padding: 0.2em 0 0.2em 1em; border-left: 3px solid var(--log-accent); color: var(--log-ink); text-align: var(--log-style-align, left); }
.log-style-italic .qt { font-style: italic; }
.pro { margin: 0 0 1.6em; }
.pro-h { margin: 0 0 0.7em; font-size: 1.1em; letter-spacing: 0.4em; color: var(--log-ink); }
.pro-b { padding-left: 1em; border-left: 1px solid var(--log-rule); color: var(--log-ink); }
.hd { margin: 1.5em 0 0.9em; padding-bottom: 0.2em; border-bottom: 1px solid var(--log-ink); font-size: 1.05em; letter-spacing: 0.12em; color: var(--log-ink); break-after: avoid; }
[data-log-level="1"] .hd { margin-top: 2em; padding: 0.35em 0; border-top: 2px solid var(--log-ink); border-bottom: 2px solid var(--log-ink); text-align: center; font-size: 1.35em; letter-spacing: 0.4em; }
[data-log-level="3"] .hd { border-bottom: 0; font-size: 0.95em; font-weight: 400; color: var(--log-muted); }
[data-log-level="3"] .hd::before { content: "—— "; }
.toc { break-after: page; }
.toc-h { margin: 0 0 1em; text-align: center; font-size: 1.3em; letter-spacing: 0.5em; }
.toc .log-toc-item { padding: 0.2em 0; border-bottom: 1px dotted var(--log-rule); }
.cu { margin: 1em 0; padding: 0.8em 1em; border: 1px solid var(--log-rule); break-inside: avoid; }
.log-style-accent .cu { border: 2px solid var(--log-accent); }
.cu-title { margin-bottom: 0.3em; font-weight: 700; color: var(--log-accent); }
.cu-note { margin: 0.4em 0 0; font-size: 0.85em; color: var(--log-muted); }
.ph { width: 100%; display: flex; justify-content: space-between; gap: 1em; letter-spacing: 0.08em; }
.pf { width: 100%; text-align: center; }
.pf-num::before { content: "— "; }
.pf-num::after { content: " —"; }
.sc-whisper { color: var(--log-ink); font-style: normal; letter-spacing: 0.02em; }
.sc-dir-to { display: block; font-size: 0.75em; color: var(--log-ink); overflow-wrap: anywhere; }
.log-merged .sc-dir-to { display: none; }
.sc-cue { margin-bottom: 0.1em; font-size: 0.8em; line-height: 1.5; color: var(--log-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sc-cue-who { font-weight: 700; }
.sc-line .log-embed { margin: 0.2em 0; padding: 0.3em 0.7em; border: 1px solid var(--log-rule); }
.sc-line .log-embed--world-clue, .sc-dir-line .log-embed--world-clue { padding: 0; border: 0; background: none; }
.log-clue { margin: 0.3em 0; padding: 0.3em 0.8em 0.45em; border-top: 2px solid var(--log-ink); border-bottom: 1px solid var(--log-ink); color: var(--log-ink); }
.log-clue + .log-clue { margin-top: 0.5em; }
.log-clue__head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 0.4em; margin-bottom: 0.2em; break-inside: avoid; break-after: avoid; }
.log-clue__label, .log-clue__kind { padding: 0; border: 0; }
.log-clue__label { font-size: 0.85em; letter-spacing: 0.1em; color: var(--log-muted); }
.log-clue__label::before { content: "【"; }
.log-clue__label::after { content: "】"; }
.log-clue__title { min-width: 0; font-weight: 700; letter-spacing: 0.06em; overflow-wrap: anywhere; }
.log-clue__kind { font-size: 0.8em; color: var(--log-muted); }
.log-clue__kind::before { content: "（"; }
.log-clue__kind::after { content: "）"; }
.log-clue__body { padding-left: 1.5em; font-size: 0.92em; }
.log-clue__body--empty { color: var(--log-muted); }
.log-clue__media { padding-left: 1.5em; break-inside: avoid; }
.sc-line .log-clue__media img, .sc-dir-line .log-clue__media img { display: block; max-width: 100%; max-height: 13em; margin: 0.2em 0 0.3em; border: 1px solid var(--log-rule); }
.log-clue__media--missing { font-size: 0.85em; color: var(--log-muted); }
.log-clue__source { margin-top: 0.2em; padding-left: 1.5em; font-size: 0.78em; color: var(--log-muted); overflow-wrap: anywhere; }
.log-clue__source-label::before { content: "※ "; }
